inline int bsearch (const SearchType &x) const
  {
    /* Hand-coded bsearch here since this is in the hot inner loop. */
    const Type *arr = this->arrayZ;
    int min = 0, max = (int) this->len - 1;
    while (min <= max)
    {
      int mid = (min + max) / 2;
      int c = arr[mid].cmp (x);
      if (c < 0)
        max = mid - 1;
      else if (c > 0)
        min = mid + 1;
      else
        return mid;
    }
    return -1;
  }
};

/*
 * Binary-search arrays
 */

template <typename LenType=HBUINT16>
struct BinSearchHeader
{
  inline operator uint32_t (void) const { return len; }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this));
  }

  inline void set (unsigned int v)
  {
    len.set (v);
    assert (len == v);
    entrySelector.set (MAX (1u, hb_bit_storage (v)) - 1);
    searchRange.set (16 * (1u << entrySelector));
    rangeShift.set (v * 16 > searchRange
                    ? 16 * v - searchRange
                    : 0);
  }

  protected:
  LenType       len;
  LenType       searchRange;
  LenType       entrySelector;
  LenType       rangeShift;

  public:
  DEFINE_SIZE_STATIC (8);
};

template <typename Type, typename LenType=HBUINT16>
struct BinSearchArrayOf : SortedArrayOf<Type, BinSearchHeader<LenType> > {};

struct VarSizedBinSearchHeader
{

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this));
  }

  HBUINT16      unitSize;       /* Size of a lookup unit for this search in bytes. */
  HBUINT16      nUnits;         /* Number of units of the preceding size to be searched. */
  HBUINT16      searchRange;    /* The value of unitSize times the largest power of 2
                                 * that is less than or equal to the value of nUnits. */
  HBUINT16      entrySelector;  /* The log base 2 of the largest power of 2 less than
                                 * or equal to the value of nUnits. */
  HBUINT16      rangeShift;     /* The value of unitSize times the difference of the
                                 * value of nUnits minus the largest power of 2 less
                                 * than or equal to the value of nUnits. */
  public:
  DEFINE_SIZE_STATIC (10);
};
